const body = $json.payload || $json.body?.payload || $json;
const se = body.scheduled_event || body.event || {};
const eventTypeName = se.name || '';

// Heuristic: this is meant to catch bookings made through
// https://calendly.com/d/dz6d-wr6-6bf/research-with-n8n
// Verify against a real webhook payload and tighten if needed (e.g. match
// on the event_type URI's UUID instead once known).
const isCdBooking = /research\s*(with)?\s*n8n/i.test(eventTypeName);
if (!isCdBooking) {
  return [];
}

const memberships = se.event_memberships || [];
const host = memberships[0] || {};

return [{
  json: {
    externalId: se.uri || body.uri || '',
    organizerName: host.user_name || '',
    organizerEmail: host.user_email || '',
    title: eventTypeName,
    description: (body.questions_and_answers || []).map(qa => (qa.question + ': ' + qa.answer)).join('\n'),
    startsAt: se.start_time || '',
    endsAt: se.end_time || '',
    rawPayload: JSON.stringify(body),
  }
}];

const body = $json.payload || $json.body?.payload || $json;
const se = body.scheduled_event || body.event || {};
const eventTypeName = se.name || '';

const isCdBooking = /research\s*(with)?\s*n8n/i.test(eventTypeName);
if (!isCdBooking) {
  return [];
}

return [{
  json: {
    externalId: se.uri || body.uri || '',
  }
}];

parameters.query:
UPDATE calendar_research_sessions
SET canceled_at = now()
WHERE session_type = 'continuous_discovery' AND external_id = $1;
